<?php require_once '../includes/auth.php';require_once '../config/uploads.php';$id=(int)($_GET['id']??0);$slug=preg_replace('/[^a-z0-9-]/','',strtolower($_GET['slug']??''));$q=$pdo->prepare('SELECT p.*,s.name AS store_name FROM products p JOIN stores s ON s.id=p.store_id JOIN users u ON u.id=s.user_id WHERE p.id=? AND s.slug=? AND p.available=1 AND p.moderation_status=? AND u.account_status=?');$q->execute([$id,$slug,'approved','active']);$p=$q->fetch();if(!$p)exit('Product not found');if($_SERVER['REQUEST_METHOD']==='POST'){$_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+max(1,min(99,(int)$_POST['quantity']));go('/public/cart.php?slug='.urlencode($slug));}$title=$p['name'];require '../includes/header.php';?><div class="card col-lg-7"><?php if($p['image']):?><img class="card-img-top" style="max-height:360px;object-fit:cover" src="<?=e($uploadUrl . '/' . $p['image'])?>" alt="<?=e($p['name'])?>"><?php endif;?><div class="card-body"><h1><?=e($p['name'])?></h1><p><?=e($p['description'])?></p><p><?=e($p['variations'])?></p><h3><?=money($p['price'])?></h3><form method="post"><input class="form-control" type="number" name="quantity" min="1" max="99" value="1"><button class="btn btn-success mt-2">Add to cart</button></form></div></div><?php require '../includes/footer.php';?>